CREATE OR REPLACE FUNCTION public.get_active_university_countries()
RETURNS TABLE(country TEXT)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT DISTINCT u.country
  FROM public.universities AS u
  WHERE u.is_active = TRUE
  ORDER BY u.country;
$$;
REVOKE ALL ON FUNCTION public.get_active_university_countries() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_active_university_countries() TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  meta JSONB := COALESCE(NEW.raw_user_meta_data, '{}'::JSONB);
  req_univ_id UUID;
  resolved_univ_id UUID;
BEGIN
  BEGIN
    req_univ_id := NULLIF(meta->>'university_id', '')::UUID;
  EXCEPTION WHEN OTHERS THEN
    req_univ_id := NULL;
  END;

  IF req_univ_id IS NOT NULL THEN
    SELECT id INTO resolved_univ_id
    FROM public.universities
    WHERE id = req_univ_id AND is_active = TRUE
    LIMIT 1;
  END IF;

  INSERT INTO public.profiles (
    id, university_id, full_name, email, role, matric_number,
    department, faculty, level, email_verified_at
  ) VALUES (
    NEW.id,
    resolved_univ_id,
    COALESCE(NULLIF(TRIM(meta->>'full_name'), ''), split_part(COALESCE(NEW.email, 'Student'), '@', 1)),
    LOWER(NEW.email),
    'student',
    NULLIF(TRIM(meta->>'matric_number'), ''),
    NULLIF(TRIM(meta->>'department'), ''),
    NULLIF(TRIM(meta->>'faculty'), ''),
    NULLIF(TRIM(meta->>'level'), ''),
    NEW.email_confirmed_at
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    email_verified_at = COALESCE(public.profiles.email_verified_at, EXCLUDED.email_verified_at);

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.can_claim_first_verified_campus_admin(
  target_profile_id UUID,
  target_university_id UUID,
  target_email TEXT,
  target_verified_at TIMESTAMPTZ
) RETURNS BOOLEAN
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF target_profile_id IS NULL OR target_university_id IS NULL OR target_email IS NULL
     OR target_verified_at IS NULL
     OR target_email !~* '^[^@]+@[^@]+$' THEN
    RETURN FALSE;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(target_university_id::TEXT, 0));

  RETURN EXISTS (
    SELECT 1
    FROM public.campus_settings AS settings
    JOIN auth.users AS auth_user ON auth_user.id = target_profile_id
    WHERE settings.university_id = target_university_id
      AND settings.first_verified_email_admin_claim = TRUE
      AND auth_user.email_confirmed_at = target_verified_at
      AND LOWER(auth_user.email) = LOWER(target_email)
      AND EXISTS (
        SELECT 1
        FROM unnest(settings.allowed_email_domains) AS allowed(domain)
        WHERE LOWER(BTRIM(allowed.domain)) = LOWER(SPLIT_PART(BTRIM(target_email), '@', 2))
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.profiles AS existing_admin
        WHERE existing_admin.university_id = target_university_id
          AND existing_admin.role = 'campus_admin'
          AND existing_admin.id <> target_profile_id
      )
  );
END;
$$;
REVOKE ALL ON FUNCTION public.can_claim_first_verified_campus_admin(UUID, UUID, TEXT, TIMESTAMPTZ) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.guard_profile_sensitive_columns()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT public.is_super_admin() THEN
    IF NEW.role IS DISTINCT FROM OLD.role
       AND NOT (OLD.role = 'student' AND NEW.role = 'campus_admin'
                AND NEW.university_id IS NOT DISTINCT FROM OLD.university_id
                AND public.can_claim_first_verified_campus_admin(
                  NEW.id, NEW.university_id, NEW.email, NEW.email_verified_at
                )) THEN
      RAISE EXCEPTION 'Only the first verified institutional email may claim campus administration.';
    END IF;
    IF NEW.university_id IS DISTINCT FROM OLD.university_id THEN
      IF OLD.university_id IS NOT NULL
         OR NEW.university_id IS NULL
         OR OLD.role <> 'student'
         OR NEW.role <> OLD.role
         OR OLD.onboarding_completed
         OR NOT EXISTS (
           SELECT 1
           FROM public.universities AS university
           JOIN public.campus_settings AS settings
             ON settings.university_id = university.id
           WHERE university.id = NEW.university_id
             AND university.is_active = TRUE
             AND (
               NOT settings.require_matric_number
               OR NULLIF(BTRIM(NEW.matric_number), '') IS NOT NULL
             )
             AND (
               CARDINALITY(settings.allowed_email_domains) = 0
               OR EXISTS (
                 SELECT 1
                 FROM unnest(settings.allowed_email_domains) AS allowed(domain)
                 WHERE LOWER(BTRIM(allowed.domain)) =
                   LOWER(SPLIT_PART(BTRIM(NEW.email), '@', 2))
               )
             )
         ) THEN
        RAISE EXCEPTION 'Students may select only an active campus that accepts their email and matriculation details.';
      END IF;
    END IF;
    IF NEW.email IS DISTINCT FROM OLD.email AND NOT EXISTS (
      SELECT 1 FROM auth.users AS auth_user
      WHERE auth_user.id = NEW.id AND LOWER(auth_user.email) = LOWER(NEW.email)
    ) THEN
      RAISE EXCEPTION 'Profile email must match the authentication account.';
    END IF;
    IF NEW.email_verified_at IS DISTINCT FROM OLD.email_verified_at AND NOT EXISTS (
      SELECT 1 FROM auth.users AS auth_user
      WHERE auth_user.id = NEW.id
        AND LOWER(auth_user.email) = LOWER(NEW.email)
        AND auth_user.email_confirmed_at = NEW.email_verified_at
        AND NEW.email_verified_at IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'Email verification must be confirmed by Supabase Auth.';
    END IF;
    IF NEW.is_active IS DISTINCT FROM OLD.is_active
       AND NOT public.is_campus_admin_for(OLD.university_id) THEN
      RAISE EXCEPTION 'Unauthorized account status change.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.promote_first_verified_campus_admin()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF NEW.role = 'student' AND public.can_claim_first_verified_campus_admin(
    NEW.id, NEW.university_id, NEW.email, NEW.email_verified_at
  ) THEN
    UPDATE public.profiles
    SET role = 'campus_admin'
    WHERE id = NEW.id AND role = 'student';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_promote_first_verified_campus_admin ON public.profiles;
CREATE TRIGGER trg_promote_first_verified_campus_admin
  AFTER INSERT OR UPDATE OF university_id, email_verified_at ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.promote_first_verified_campus_admin();
